// Tests connectivity and validity of credentials in .env.test

require('dotenv').config({ path: '.env.test' });
const https = require('https');
const { spawn } = require('child_process');

const results = [];

// Helper to log results
const logResult = (name, success, message) => {
  const status = success ? '✅ VALID' : '❌ INVALID/ERROR';
  console.log(`${status}: ${name} - ${message}`);
  results.push({ name, success, message });
};

// Test 1: Database connectivity
const testDatabase = () => {
  return new Promise((resolve) => {
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
      logResult('DATABASE_URL', false, 'Not set');
      resolve();
      return;
    }

    // Use psql if available to test connection, otherwise parse URL and report
    const pgClient = spawn('psql', [dbUrl, '-c', 'SELECT 1'], {
      stdio: 'pipe',
      shell: true,
    });

    let output = '';
    let errorOutput = '';

    pgClient.stdout.on('data', (data) => { output += data; });
    pgClient.stderr.on('data', (data) => { errorOutput += data; });

    pgClient.on('close', (code) => {
      if (code === 0) {
        logResult('DATABASE_URL', true, 'Connection successful');
      } else {
        logResult('DATABASE_URL', false, errorOutput.substring(0, 100));
      }
      resolve();
    });

    pgClient.on('error', (err) => {
      logResult('DATABASE_URL', false, `Cannot connect: ${err.message}`);
      resolve();
    });

    // Timeout after 10 seconds
    setTimeout(() => {
      pgClient.kill();
      logResult('DATABASE_URL', false, 'Connection timed out');
      resolve();
    }, 10000);
  });
};

// Test 2: AWS credentials
const testAWS = () => {
  return new Promise((resolve) => {
    const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKeyId || !secretKey) {
      logResult('AWS', false, 'Missing credentials');
      resolve();
      return;
    }

    // AWS STS GetCallerIdentity is a safe, read-only API call
    const stsEndpoint = 'sts.amazonaws.com';
    const region = 'us-east-1';

    // Create AWS Signature Version 4 signature manually is complex,
    // so we'll just check if the key format looks correct
    if (accessKeyId.startsWith('AKIA') && accessKeyId.length === 20) {
      // Format looks valid, but can't verify without full signature
      logResult('AWS', true, 'Key format valid (actual verification requires AWS API call)');
    } else {
      logResult('AWS', false, 'Invalid key format');
    }
    resolve();
  });
};

// Test 3: Anthropic API key
